// ESCRITURA DE DATOS EN TIEMPO REAL
// =========================================================================

function updateTableInSheet(ss, table) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();

  const rowValues = [
    table.id,
    table.name,
    table.capacity,
    table.status,
    table.occupiedByWaiterId || '',
    table.occupiedByWaiterName || '',
    table.currentOrderId || '',
    table.occupiedSince || new Date().toISOString()
  ];

  if (lastRow > 1) {
    const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) {
      if (String(ids[i][0]) === String(table.id)) {
        sheet.getRange(i + 2, 1, 1, 8).setValues([rowValues]);
        return;
      }
    }
  }
  sheet.appendRow(rowValues);
}

function releaseTableInSheet(ss, tableId, orderId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (sheet) {
    const lastRow = sheet.getLastRow();
    if (lastRow > 1) {
      const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < ids.length; i++) {
        if (String(ids[i][0]) === String(tableId)) {
          sheet.getRange(i + 2, 4, 1, 5).setValues([['libre', '', '', '', '']]);
          break;
        }
      }
    }
  }

  // Limpiar o anular órdenes no cobradas asociadas a esta mesa en ORDENES
  const sheetOrdenes = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (sheetOrdenes) {
    const lastRowO = sheetOrdenes.getLastRow();
    if (lastRowO > 1) {
      for (var j = lastRowO; j >= 2; j--) {
        const rowId = String(sheetOrdenes.getRange(j, 1).getValue());
        const rowTableId = String(sheetOrdenes.getRange(j, 3).getValue());
        const rowStatus = String(sheetOrdenes.getRange(j, 6).getValue());
        const rawItems = sheetOrdenes.getRange(j, 8).getValue();

        var itemCount = 0;
        try {
          const parsed = JSON.parse(rawItems || '[]');
          itemCount = Array.isArray(parsed) ? parsed.length : 0;
        } catch(e) {
          itemCount = 0;
        }

        const matches = (orderId && rowId === String(orderId)) || (rowTableId === String(tableId));
        if (matches && rowStatus !== 'cobrada') {
          if (itemCount === 0 || rowStatus === 'abierta') {
            sheetOrdenes.deleteRow(j);
          } else {
            sheetOrdenes.getRange(j, 6).setValue('cancelada');
          }
        }
      }
    }
  }
}

function cancelOrderInSheet(ss, orderOrTicketId, tableId) {
  const sheetOrdenes = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheetOrdenes) return;
  const lastRow = sheetOrdenes.getLastRow();
  if (lastRow <= 1) return;

  const cleanId = String(orderOrTicketId).replace('kt-', '');
  for (var j = lastRow; j >= 2; j--) {
    const rowId = String(sheetOrdenes.getRange(j, 1).getValue());
    const rowTableId = String(sheetOrdenes.getRange(j, 3).getValue());
    const rawItems = sheetOrdenes.getRange(j, 8).getValue();

    var itemCount = 0;
    try {
      const parsed = JSON.parse(rawItems || '[]');
      itemCount = Array.isArray(parsed) ? parsed.length : 0;
    } catch(e) {
      itemCount = 0;
    }

    if (rowId === cleanId || (tableId && rowTableId === String(tableId))) {
      if (itemCount === 0) {
        sheetOrdenes.deleteRow(j);
      } else {
        sheetOrdenes.getRange(j, 6).setValue('cancelada');
      }
      return;
    }
  }
}

function removeEmptyOrdersFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  for (var i = lastRow; i >= 2; i--) {
    const rawItems = sheet.getRange(i, 8).getValue();
    const status = String(sheet.getRange(i, 6).getValue());
    var isEmpty = false;
    try {
      const parsed = JSON.parse(rawItems || '[]');
      if (!Array.isArray(parsed) || parsed.length === 0) {
        isEmpty = true;
      }
    } catch(e) {
      isEmpty = !rawItems || String(rawItems).trim() === '' || String(rawItems).trim() === '[]';
    }

    if (isEmpty && status !== 'cobrada') {
      sheet.deleteRow(i);
    }
  }
}

function saveOrderInSheet(ss, order) {
  // NUNCA guardar órdenes vacías sin platos en ORDENES
  if (!order || !Array.isArray(order.items) || order.items.length === 0) {
    return;
  }

  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  const itemsJson = JSON.stringify(order.items || []);

  const rowValues = [
    order.id,
    order.orderNumber,
    order.tableId,
    order.tableName,
    order.waiterName,
    order.status || 'en_cocina',
    order.currentRound || 1,
    itemsJson,
    order.createdAt || new Date().toISOString(),
    new Date().toISOString()
  ];

  if (lastRow > 1) {
    const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) {
      if (String(ids[i][0]) === String(order.id)) {
        sheet.getRange(i + 2, 1, 1, 10).setValues([rowValues]);
        return;
      }
    }
  }
  sheet.appendRow(rowValues);
}

function updateOrderStatusInSheet(ss, orderOrTicketId, status, itemId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  // Extraer ID limpio
  const cleanId = String(orderOrTicketId).replace('kt-', '');
  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();

  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === cleanId) {
      const rowNum = i + 2;

      // Si la fila estaba vacía sin platos, eliminarla inmediatamente
      const currentJson = sheet.getRange(rowNum, 8).getValue();
      var items = [];
      try { items = JSON.parse(currentJson || '[]'); } catch(e) {}
      if (!Array.isArray(items) || items.length === 0) {
        sheet.deleteRow(rowNum);
        return;
      }

      if (status) {
        sheet.getRange(rowNum, 6).setValue(status);
      }
      if (itemId) {
        // Actualizar item específico dentro de JSON
        try {
          const updated = items.map(function(it) {
            return it.id === itemId ? Object.assign({}, it, { status: status }) : it;
          });
          sheet.getRange(rowNum, 8).setValue(JSON.stringify(updated));
        } catch(e) {}
      }
      sheet.getRange(rowNum, 10).setValue(new Date().toISOString());
      return;
    }
  }
}

function requestBillInSheet(ss, tableId, orderId) {
  const mSheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (mSheet) {
    const lastRow = mSheet.getLastRow();
    if (lastRow > 1) {
      const ids = mSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < ids.length; i++) {
        if (String(ids[i][0]) === String(tableId)) {
          mSheet.getRange(i + 2, 4).setValue('cuenta_solicitada');
          break;
        }
      }
    }
  }

  if (orderId) {
    const oSheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
    if (oSheet) {
      const lastRowO = oSheet.getLastRow();
      if (lastRowO > 1) {
        const idsO = oSheet.getRange(2, 1, lastRowO - 1, 1).getValues();
        for (var j = 0; j < idsO.length; j++) {
          if (String(idsO[j][0]) === String(orderId)) {
            oSheet.getRange(j + 2, 6).setValue('por_cobrar');
            break;
          }
        }
      }
    }
  }
}

function markOrderAsPaid(ss, orderNumber) {
  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  const orders = sheet.getRange(2, 2, lastRow - 1, 1).getValues();
  for (var i = 0; i < orders.length; i++) {
    if (String(orders[i][0]) === String(orderNumber)) {
      sheet.getRange(i + 2, 6).setValue('cobrada');
      sheet.getRange(i + 2, 10).setValue(new Date().toISOString());
      return;
    }
  }
}

