function deletePaymentFromSheet(ss, orderNumber, paymentDate) {
  const sheet = ss.getSheetByName(SHEET_NAMES.VENTAS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return;

  const data = sheet.getRange(2, 1, lastRow - 1, 2).getValues();
  for (let i = data.length - 1; i >= 0; i--) {
    const rowDate = String(data[i][0] || '').trim();
    const rowOrder = String(data[i][1] || '').trim();

    let match = false;
    if (orderNumber && rowOrder === String(orderNumber).trim()) {
      if (!paymentDate || rowDate === String(paymentDate).trim()) {
        match = true;
      }
    } else if (!orderNumber && paymentDate && rowDate === String(paymentDate).trim()) {
      match = true;
    }

    if (match) {
      sheet.deleteRow(i + 2);
      return;
    }
  }
}

function saveMenuItemInSheet(ss, dish) {
  const sheet = ss.getSheetByName(SHEET_NAMES.PLATOS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();

  // Asegurar que existan encabezados hasta la columna I (Columna 9)
  if (sheet.getLastColumn() < 9) {
    sheet.getRange(1, 8).setValue('PRECIO_BS');
    sheet.getRange(1, 9).setValue('FOTO_URL');
  }

  const bcvRate = getBcvRateFromSheet(ss);
  const precioBs = Number(((Number(dish.price) || 0) * bcvRate).toFixed(2));
  const rowValues = [
    dish.id,
    dish.name,
    dish.category,
    Number(dish.price) || 0,
    dish.description || '',
    dish.available ? 'SI' : 'NO',
    Number(dish.preparationTimeMinutes) || 10,
    precioBs,
    dish.image || '' // Columna I: Enlace de foto en Google Drive
  ];

  if (lastRow > 1) {
    const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) {
      if (String(ids[i][0]) === String(dish.id)) {
        sheet.getRange(i + 2, 1, 1, 9).setValues([rowValues]);
        return;
      }
    }
  }
  sheet.appendRow(rowValues);
}

/**
 * Sube una foto a Google Drive en la carpeta "ComandaPro_Platos",
 * le otorga permisos públicos de lectura y actualiza la Columna I en la tabla PLATOS.
 */
function uploadDishPhotoToDrive(ss, base64Data, mimeType, dishId, dishName) {
  if (!base64Data) {
    throw new Error('No se recibió el contenido de la imagen');
  }

  var rawBase64 = base64Data;
  var detectedMime = mimeType || 'image/jpeg';
  if (base64Data.indexOf(';base64,') !== -1) {
    var parts = base64Data.split(';base64,');
    detectedMime = parts[0].replace('data:', '') || detectedMime;
    rawBase64 = parts[1];
  }

  // Carpeta de Google Drive para los platos
  var folderName = 'ComandaPro_Platos';
  var folders = DriveApp.getFoldersByName(folderName);
  var folder;
  if (folders.hasNext()) {
    folder = folders.next();
  } else {
    folder = DriveApp.createFolder(folderName);
  }

  var ext = detectedMime.indexOf('png') !== -1 ? 'png' : (detectedMime.indexOf('webp') !== -1 ? 'webp' : 'jpg');
  var safeName = (dishName || 'plato').replace(/[^a-zA-Z0-9_-]/g, '_');
  var fileName = 'plato_' + (dishId || Date.now()) + '_' + safeName + '.' + ext;

  var decodedBytes = Utilities.base64Decode(rawBase64);
  var blob = Utilities.newBlob(decodedBytes, detectedMime, fileName);
  var file = folder.createFile(blob);

  // Permiso para que cualquiera con el enlace pueda visualizar la foto del plato
  try {
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
  } catch (e) {
    // Si la organización restringe compartir externamente, continuar
  }

  var fileId = file.getId();
  // Enlace directo compatible con previsualización en apps web
  var driveThumbnailUrl = 'https://drive.google.com/thumbnail?id=' + fileId + '&sz=w1000';
  var webViewUrl = 'https://drive.google.com/uc?export=view&id=' + fileId;

  // Registrar directamente en la Columna I de la tabla "PLATOS"
  if (dishId) {
    setDishPhotoInSheet(ss, dishId, driveThumbnailUrl);
  }

  return {
    fileId: fileId,
    driveUrl: driveThumbnailUrl,
    viewUrl: webViewUrl,
    folder: folderName,
    fileName: fileName
  };
}

